package cn.materialbox.app;
import android.app.Instrumentation;import android.os.Bundle;import android.content.Context;import android.graphics.*;import android.graphics.pdf.PdfDocument;import org.json.*;import java.io.*;import com.arthenica.ffmpegkit.*;
public class DeviceChecks extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private void check(boolean b,String message){if(!b)throw new AssertionError(message);}
 private JSONObject rust(String op,Object input)throws Exception{JSONObject r=new JSONObject(Core.call(op,input.toString()));check(r.optBoolean("ok"),op+": "+r.optString("error"));return r.getJSONObject("data");}
 public void onStart(){Bundle report=new Bundle();int checks=0;Context c=getTargetContext();File root=new File(c.getFilesDir(),"device-checks");root.mkdirs();
  try{
   JSONObject sha=rust("tool",new JSONObject().put("action","sha256").put("text","abc"));check(sha.getString("text").startsWith("ba7816bf"),"SHA256");checks++;
   JSONObject encoded=rust("tool",new JSONObject().put("action","base64-encode").put("text","材料魔盒 🐉"));JSONObject decoded=rust("tool",new JSONObject().put("action","base64-decode").put("text",encoded.getString("text")));check(decoded.getString("text").equals("材料魔盒 🐉"),"Unicode roundtrip");checks++;
   File png=new File(root,"中文 图片.png"),jpg=new File(root,"旋转 结果.jpg");jpg.delete();Bitmap bitmap=Bitmap.createBitmap(40,20,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.MAGENTA);try(OutputStream out=new FileOutputStream(png)){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();
   JSONObject image=new JSONObject().put("mode","image").put("input",png.getAbsolutePath()).put("output",jpg.getAbsolutePath()).put("format","jpg").put("width",20).put("rotate",90).put("quality",80);rust("convert",image);Bitmap result=BitmapFactory.decodeFile(jpg.getAbsolutePath());check(result.getWidth()==10&&result.getHeight()==20,"image dimensions");result.recycle();checks++;
   check(!new JSONObject(Core.call("convert",image.toString())).optBoolean("ok"),"overwrite protection");checks++;
   File txt=new File(root,"材料.txt"),docx=new File(root,"材料.docx"),back=new File(root,"还原.txt");docx.delete();back.delete();try(OutputStream out=new FileOutputStream(txt)){out.write("材料魔盒\n<中文 & emoji 🐉>".getBytes("UTF-8"));}
   rust("convert",new JSONObject().put("mode","document").put("input",txt.getAbsolutePath()).put("output",docx.getAbsolutePath()).put("format","docx"));rust("convert",new JSONObject().put("mode","document").put("input",docx.getAbsolutePath()).put("output",back.getAbsolutePath()).put("format","txt"));byte[] bytes=new byte[(int)back.length()];try(InputStream in=new FileInputStream(back)){in.read(bytes);}check(new String(bytes,"UTF-8").contains("<中文 & emoji 🐉>"),"DOCX roundtrip");checks++;
   File a=new File(root,"a.pdf"),b=new File(root,"b.pdf"),merged=new File(root,"merged.pdf"),split=new File(root,"split.pdf");merged.delete();split.delete();
   for(File f:new File[]{a,b}){PdfDocument pdf=new PdfDocument();PdfDocument.Page p=pdf.startPage(new PdfDocument.PageInfo.Builder(300,400,1).create());Paint paint=new Paint();paint.setTextSize(24);p.getCanvas().drawText("材料魔盒 / PDF",20,40,paint);pdf.finishPage(p);try(OutputStream out=new FileOutputStream(f)){pdf.writeTo(out);}pdf.close();}
   JSONObject mr=rust("convert",new JSONObject().put("mode","pdf-merge").put("input",a.getAbsolutePath()).put("inputs",new JSONArray().put(a.getAbsolutePath()).put(b.getAbsolutePath())).put("output",merged.getAbsolutePath()).put("format","pdf"));check(mr.getJSONObject("detail").getInt("pages")==2,"merge page count");checks++;
   rust("convert",new JSONObject().put("mode","pdf-split").put("input",merged.getAbsolutePath()).put("output",split.getAbsolutePath()).put("pages","2").put("format","pdf"));check(split.length()>0,"split output");checks++;
   File source=new File(root,"视频 中文.mp4");source.delete();FFmpegSession fixture=FFmpegKit.executeWithArguments(new String[]{"-y","-f","lavfi","-i","color=c=purple:s=320x240:d=1","-f","lavfi","-i","sine=frequency=440:duration=1","-c:v","libx264","-pix_fmt","yuv420p","-c:a","aac","-shortest",source.getAbsolutePath()});check(ReturnCode.isSuccess(fixture.getReturnCode()),"FFmpeg fixture: "+fixture.getAllLogsAsString());checks++;
   for(String mode:new String[]{"video","audio","gif","frame"}){String fmt=mode.equals("audio")?"mp3":mode.equals("gif")?"gif":mode.equals("frame")?"png":"mp4";File out=new File(root,mode+"."+fmt);out.delete();JSONObject plan=rust("plan",new JSONObject().put("mode",mode).put("input",source.getAbsolutePath()).put("output",out.getAbsolutePath()).put("format",fmt).put("width",mode.equals("video")?160:0).put("start",0).put("duration",1).put("quality",3).put("bitrate",128));JSONArray array=plan.getJSONArray("args");String[] args=new String[array.length()];for(int i=0;i<args.length;i++)args[i]=array.getString(i);FFmpegSession session=FFmpegKit.executeWithArguments(args);check(ReturnCode.isSuccess(session.getReturnCode()),mode+": "+session.getAllLogsAsString());check(out.length()>0,mode+" output");checks++;}
   File inputs=new File(c.getFilesDir(),"inputs");inputs.mkdirs();File uiInput=new File(inputs,"device-check.png");try(InputStream in=new FileInputStream(png);OutputStream out=new FileOutputStream(uiInput)){byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}
   Store.load(c);String id=Store.enqueue(c,new JSONObject().put("mode","image").put("input",uiInput.getAbsolutePath()).put("name","真机测试 材料.png").put("format","webp"));c.startForegroundService(new android.content.Intent(c,ConversionService.class));long deadline=System.currentTimeMillis()+15000;while(System.currentTimeMillis()<deadline&&!"done".equals(Store.find(id).optString("status"))){Thread.sleep(100);}check("done".equals(Store.find(id).optString("status")),"foreground service queue: "+Store.find(id));checks++;
   for(String extension:new String[]{"docx","pptx","xlsx","html"}){File sourceOffice=new File(root,"layout."+extension),pdfOut=new File(root,"layout-"+extension+".pdf");pdfOut.delete();try(InputStream in=c.getAssets().open("layout."+extension);OutputStream out=new FileOutputStream(sourceOffice)){byte[] bb=new byte[65536];int n;while((n=in.read(bb))!=-1)out.write(bb,0,n);}OfficeClient.convert(c,new JSONObject().put("mode","office-pdf").put("input",sourceOffice.getAbsolutePath()).put("output",pdfOut.getAbsolutePath()).put("format","pdf"));check(pdfOut.length()>100,"Office "+extension+" output");android.graphics.pdf.PdfRenderer renderer=new android.graphics.pdf.PdfRenderer(android.os.ParcelFileDescriptor.open(pdfOut,android.os.ParcelFileDescriptor.MODE_READ_ONLY));check(renderer.getPageCount()>0,"Office "+extension+" valid PDF");renderer.close();checks++;}
   for(String extension:new String[]{"docx","pptx"}){File pdfIn=new File(root,"layout-"+extension+".pdf"),editable=new File(root,"pdf-editable."+extension);editable.delete();OfficeClient.convert(c,new JSONObject().put("mode","office-editable").put("input",pdfIn.getAbsolutePath()).put("output",editable.getAbsolutePath()).put("format",extension));check(editable.length()>100,"PDF editable "+extension);java.util.zip.ZipFile zip=new java.util.zip.ZipFile(editable);String entry=extension.equals("docx")?"word/document.xml":"ppt/slides/slide1.xml";java.util.zip.ZipEntry ze=zip.getEntry(entry);check(ze!=null,"editable document XML");ByteArrayOutputStream os=new ByteArrayOutputStream();try(InputStream in=zip.getInputStream(ze)){byte[] bb=new byte[8192];int n;while((n=in.read(bb))!=-1)os.write(bb,0,n);}String xml=new String(os.toByteArray(),"UTF-8");check(xml.contains(extension.equals("docx")?"<w:t":"<a:t"),"editable text objects, not page screenshots");zip.close();checks++;
    if(extension.equals("docx")){check(xml.contains("<w:tbl>"),"PDF Word table remains an editable table");check(xml.contains("6A3EA1")||xml.contains("6A3EA0")||xml.contains("6A3EA2"),"PDF Word original purple text color");}else {check(xml.contains("<a:tbl>"),"PPT table remains an editable table");check(xml.contains("4F81BD")||xml.contains("4F81BC")||xml.contains("4F81BE"),"PPT table background color retained");}
    File roundtrip=new File(root,"roundtrip-"+extension+".pdf");roundtrip.delete();OfficeClient.convert(c,new JSONObject().put("mode","office-pdf").put("input",editable.getAbsolutePath()).put("output",roundtrip.getAbsolutePath()).put("format","pdf"));
    android.graphics.pdf.PdfRenderer rr=new android.graphics.pdf.PdfRenderer(android.os.ParcelFileDescriptor.open(roundtrip,android.os.ParcelFileDescriptor.MODE_READ_ONLY));
    android.graphics.pdf.PdfRenderer original=new android.graphics.pdf.PdfRenderer(android.os.ParcelFileDescriptor.open(pdfIn,android.os.ParcelFileDescriptor.MODE_READ_ONLY));
    check(rr.getPageCount()==original.getPageCount(),"editable "+extension+" roundtrip page count");
    for(int renderIndex=0;renderIndex<2;renderIndex++){android.graphics.pdf.PdfRenderer render=renderIndex==0?original:rr;android.graphics.pdf.PdfRenderer.Page page=render.openPage(0);Bitmap preview=Bitmap.createBitmap(page.getWidth()*2,page.getHeight()*2,Bitmap.Config.ARGB_8888);preview.eraseColor(Color.WHITE);page.render(preview,null,null,android.graphics.pdf.PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);try(OutputStream previewOut=new FileOutputStream(new File(root,(renderIndex==0?"original-":"roundtrip-")+extension+".png"))){preview.compress(Bitmap.CompressFormat.PNG,100,previewOut);}preview.recycle();page.close();}
    rr.close();original.close();checks++;
   }
   File tablePdf=new File(root,"layout-xlsx.pdf"),sheetOut=new File(root,"table-editable.xlsx");sheetOut.delete();PdfTables.convert(c,new JSONObject().put("mode","pdf-excel").put("input",tablePdf.getAbsolutePath()).put("output",sheetOut.getAbsolutePath()).put("format","xlsx"));java.util.zip.ZipFile sheetZip=new java.util.zip.ZipFile(sheetOut);java.util.zip.ZipEntry sheetEntry=sheetZip.getEntry("xl/worksheets/sheet1.xml");check(sheetEntry!=null,"spreadsheet cells");ByteArrayOutputStream sheetBytes=new ByteArrayOutputStream();try(InputStream in=sheetZip.getInputStream(sheetEntry)){byte[] bb=new byte[8192];int n;while((n=in.read(bb))!=-1)sheetBytes.write(bb,0,n);}String sheetXml=new String(sheetBytes.toByteArray(),"UTF-8");check(sheetXml.contains("Dragon")&&sheetXml.contains(">12</v>"),"editable spreadsheet text and numeric cell");sheetZip.close();checks++;
   File rebuiltSheetPdf=new File(root,"table-rebuilt.pdf");rebuiltSheetPdf.delete();OfficeClient.convert(c,new JSONObject().put("mode","office-pdf").put("input",sheetOut.getAbsolutePath()).put("output",rebuiltSheetPdf.getAbsolutePath()).put("format","pdf"));check(rebuiltSheetPdf.length()>0,"rebuilt spreadsheet reopens in Office");checks++;
   File imagePdf=new File(root,"image-source.pdf");imagePdf.delete();rust("convert",new JSONObject().put("mode","image-pdf").put("input",png.getAbsolutePath()).put("output",imagePdf.getAbsolutePath()).put("format","pdf"));File imageZip=new File(root,"pdf-images.zip");imageZip.delete();PdfLocal.images(new JSONObject().put("mode","pdf-image").put("input",imagePdf.getAbsolutePath()).put("output",imageZip.getAbsolutePath()).put("format","zip").put("action","png").put("width",144));check(imageZip.length()>0,"image PDF and raster ZIP");checks++;
   File pdfa=new File(root,"archive-a2b.pdf");pdfa.delete();OfficeClient.convert(c,new JSONObject().put("mode","office-pdfa").put("input",tablePdf.getAbsolutePath()).put("output",pdfa.getAbsolutePath()).put("format","pdf").put("options","{\"SelectPdfVersion\":{\"type\":\"long\",\"value\":\"2\"}}"));check(pdfa.length()>0,"PDF/A export produced file");checks++;
   File packaged=new File(root,"layout-package.pptx"),packagedPdf=new File(root,"layout-package.pdf");packaged.delete();packagedPdf.delete();rust("convert",new JSONObject().put("mode","office-package").put("input",new File(root,"layout.pptx").getAbsolutePath()).put("output",packaged.getAbsolutePath()).put("format","pptx"));OfficeClient.convert(c,new JSONObject().put("mode","office-pdf").put("input",packaged.getAbsolutePath()).put("output",packagedPdf.getAbsolutePath()).put("format","pdf"));check(packagedPdf.length()>0,"normalized OOXML JNI and native Office conversion");checks++;
   report.putString("result","DEVICE_CHECKS_PASS: "+checks+" real Android JNI/file/FFmpeg/PDF/foreground service/Office checks");report.putString("fixtureInput",uiInput.getAbsolutePath());report.putString("taskId",id);report.putInt("checks",checks);finish(-1,report);
  }catch(Throwable e){report.putString("result","DEVICE_CHECKS_FAIL after "+checks+": "+e);StringWriter log=new StringWriter();e.printStackTrace(new PrintWriter(log));report.putString("trace",log.toString());finish(1,report);}
 }
}

